// =====================================================
// دعاء بدء دلائل الخيرات — يُقرأ قبل بدء كل حزب
// =====================================================
const String dalailOpeningDua =
    'الحمد لله رب العالمين، وحسبي الله ونعم الوكيل، ولا حول ولا قوة إلا بالله العلي العظيم، الله إني أبرء إليك من حولي وقوتي إلى حولك وقوتك، اللهم إني نويت بالصلاة على النبي صلى الله عليه وسلم امتثالاً لأمرك وتصديقاً لنبيك سيدنا محمد صلى الله عليه وسلم ومحبةً فيه وشوقاً إليه وتعظيماً لقدره ولكونه أهلاً لذلك فتقبلها مني بفضلك وإحسانك، وأزِلْ حجاب الغفلة عن قلبي واجعلني من عبادك الصالحين، اللهم زده شرفاً على شرفه الذي أوليته، وعزاً على عزه الذي أعطيته، ونوراً على نوره الذي منه خلقته، وأعل مقامه في مقامات المرسلين ودرجته في درجات النبيين، وأسألُكَ رِضاكَ ورضاه يا رب العالمين، مع العافية الدائمة، والموت على الكتاب والسنة والجماعة، وكلمتي الشهادة على تحقيقها من غير تغيير ولا تبديل، واغفر لي ما ارتكبته بمنك وفضلك وجودك وكرمك يا أكرم الأكرمين، وصلى الله على سيدنا محمد و آله وصحبه وسلم.';

// =====================================================
// دعاء يُقرأ عَقِبَ دلائل الخيرات — يُقرأ بعد كل حزب
// =====================================================
const String dalailClosingDua =
    'اللهم اغفر لمؤلفه وارحمه واجعله من المحشورين في زمرة النبيين والصديقين يوم القيامة بفضلك يا أرحم الراحمين، اللهم امين علينا بصفاء المعرفة وهب لنا صحيح المعاملة بيننا وبينك على السنة والجماعة، وصدق التوكل عليك، وحسن الظن بك، وامتن علينا بكل ما يُقربنا إليك مقروناً بالعفو في الدارين يا رب العالمين، وحسبنا الله وكفى وسلام على عباده الذين اصطفى، وسلام على المرسلين، والحمد الله رب العالمين. اللهم اشرح بالصلاة عليهِ صُدُورَنا، ويسر بها أمورنا، وفرج بها همومنا، واكشف بها غُمُومنا، واغفر بها ذُنُوبَنَا، واقض بها ديوننا، وأصلح بها أحوالنا، وبلغ بها آمالنا، وتقبل بها توبتنا، واغسل بها حوبتنا، وانصر بها حجتنا، وطهر بها ألسنتنا، وآنس بها وحشتنا، وارحم بها غربتنا، واجعلها نوراً بين أيدينا ومن خلفنا، وعن أيماننا وعن شمائلنا، ومن فوقنا ومن تحتنا، وفي حياتنا وموتنا، وفي قبورنا وحشرنا ونشرنا، وظلا يوم القيامة على رؤوسنا، وثقل بها يا رب موازين حسناتنا، وأدم بركاتها علينا حتى نلقى نبينا وسيدنا محمداً صلى الله عليه وسلم ونحنُ آمِنُونَ مُطْمَئِنُّونَ، فَرِحُونَ مُسْتَبْشِرُونَ، ولا تفرق بيننا وبينه حتى تُدْخِلَنَا مَدْخَلَهُ، وتاوينا إلى جواره الكريم، مع الذين أنعمت عليهم من النبيين والصديقين والشهداء والصالحين، وحسن أولئك رفيقاً، اللهم إنا آمنا به صلى الله عليه وسلم ولم نره، فمتعنا اللهم في الدارين برؤيته، وثبت قلوبنا على محبته، واستعملنا على سنته، وتوفنا على ملته، واحشرنا في زمرته الناجية وحزبه المفلحين، وانفعنا بما انطوت عليه قلوبنا من محبته صلى الله عليه وسلم يوم لا جد ولا مال ولا بنين، وأوردنا حوضه الأصفى، واسقنا بكأسه الأوفى، ويسر علينا زيارة حرمك وحرمه من قبل أن تُميتنا، وأدم علينا الإقامة بحرمك وحرمه صلى الله عليه وسلم إلى أن تتوفى، اللهم إنا نستشفع بِهِ إليك، إذ هو أَوْجَهُ الشَّفَعاء إليكَ، ونُقْسِمُ بِهِ عليكَ إذْ هو أَعْظَمُ مِنْ أُقْسِم بحقه عليكَ، وَتَتَوَكَّلُ بِهِ إِليكَ، إِذْ هو أَقْرَبُ الوسائل إليكَ، نَشْكُو إِليكَ يا رَبِّ قَسْوَةَ قُلُوبِنا وكَثرَةَ ذُنُوبِنا، وطُولَ آمالنا، وفَسَادَ أعمالنا، وتكاسلنا عن الطاعات، وهجومنا على المخالفاتِ، فَنِعْمَ المُشْتَكَى إِليهِ أَنتَ يَا رَبِّ بِكَ نَسْتَنْصِرُ على أعدائنا وأنفسنا فانصرنا، وعلى فضلك نتوكل في صلاحنا فلا تكلنا إلى غيرك يا ربنا، وإلى جناب رسولك صلى الله عليه وسلم تنتَسِبُ فلا تبعدنا، وبِبَابِكَ نَقِفُ فلا تَطْرُدْنا وإِيَّاكَ نسألُ فلا تخيبنا، اللهم ارحم تضرعنا، وآمن خوفنا، وتقبل أعمالنا، وأصلح أحوالنا، واجعل بطاعتك اشتغالنا، وإلى الخير مالنا، وحقق بالزيادة آمالنا، واختم بالسعادة اجالنا، هذا ذلنا ظاهر بين يديك، وحالنا لا يخفى عليك، أمرتنا فتركنا، ونهيتنا فارتكبنا، ولا يسعنا إلا عَفُوكَ فاعفُ عنا، يا خير مَأْمُولٍ، وأكرم مسؤول، إنك عفو كريم، رؤوف رحيم، يا أرحم الراحمين، وصلى الله على سيدنا محمد وعلى آله وصحبه وسلم تسليماً، والحمد لله رب العالمين. اللهم يا من لطفت بخلق السماوات والأرض ولطفت بالأجنة في بطون أمهاتها، الطف بنا في قضائك وقدرك، لطفاً يليق بكرمك، يا أرحم الراحمين (ثلاثاً) ، اللهم انصر بفضلك سلطاننا، وأهلك الكفرة أعداءنا، وآمنا في أوطاننا، وَوَلِّ أُمُورَنا خيارنا، ولا تُوَلِّ أمورنا شرارنا، وارفع مقتك وغضبك عنا، ولا تُسَلِّط علينا بِذُنُوبِنا من لا يخافك ولا يرحمنا، يا رب العالمين.';

enum DalailDay {
  saturday,
  sunday,
  monday,
  tuesday,
  wednesday,
  thursday,
  friday,
}

extension DalailDayExtension on DalailDay {
  String get arabicName {
    switch (this) {
      case DalailDay.saturday:
        return 'يوم السبت';
      case DalailDay.sunday:
        return 'يوم الأحد';
      case DalailDay.monday:
        return 'يوم الاثنين';
      case DalailDay.tuesday:
        return 'يوم الثلاثاء';
      case DalailDay.wednesday:
        return 'يوم الأربعاء';
      case DalailDay.thursday:
        return 'يوم الخميس';
      case DalailDay.friday:
        return 'يوم الجمعة';
    }
  }

  String get shortName {
    switch (this) {
      case DalailDay.saturday:
        return 'السبت';
      case DalailDay.sunday:
        return 'الأحد';
      case DalailDay.monday:
        return 'الاثنين';
      case DalailDay.tuesday:
        return 'الثلاثاء';
      case DalailDay.wednesday:
        return 'الأربعاء';
      case DalailDay.thursday:
        return 'الخميس';
      case DalailDay.friday:
        return 'الجمعة';
    }
  }

  int get dayIndex {
    switch (this) {
      case DalailDay.saturday:
        return DateTime.saturday;
      case DalailDay.sunday:
        return DateTime.sunday;
      case DalailDay.monday:
        return DateTime.monday;
      case DalailDay.tuesday:
        return DateTime.tuesday;
      case DalailDay.wednesday:
        return DateTime.wednesday;
      case DalailDay.thursday:
        return DateTime.thursday;
      case DalailDay.friday:
        return DateTime.friday;
    }
  }
}

/// الحزب المخصص لكل يوم (سيتم إضافة المحتوى لاحقاً)
class DalailDaySection {
  final DalailDay day;
  final String hizb; // رقم الحزب
  final String content; // سيتم إضافته لاحقاً

  const DalailDaySection({
    required this.day,
    required this.hizb,
    this.content = '',
  });
}

final Map<DalailDay, DalailDaySection> dalailSchedule = {
  // ══════════════════════════════════════════
  // الحزب السادس — يوم السبت
  // ══════════════════════════════════════════
  DalailDay.saturday: DalailDaySection(
    day: DalailDay.saturday,
    hizb: 'الحزب السادس',
    content: '''بسم الله الرحمن الرحيم اللهم رَبَّ الأرواح والأجسادِ البَالِيةِ، أسألُكَ بِطَاعَةِ الأرْوَاحِ الرَّاجِعَةِ إِلى أَجْسَادِهَا وبِطَاعَةِ الأَجْسَادِ الْمُلْتَئِمَةِ بِعُرُوقِهَا، وَبِكَلِمَاتِكَ النَّافِذَةِ فيهم، وأخذك الحق منهم والخَلَائِقُ بَيْنَ يَدَيْكَ ينتظرونَ فَصَلَ قَضَائِكَ ويَرْجُونَ رَحْمَتَكَ ويَخَافُونَ عِقَابَكَ، أن تجعل النُّورَ في بَصَرِي، وذِكْرَكَ بِالليل والنَّهَارِ على لِسَانِي وعَمَلاً صَالِحاً فَارْزُقْنِي، اللهم صل على سيدنا محمد كما صليت على سيدنا إبراهيم، وبارك على سيدنا محمد كما باركت على سيدنا إبراهيم، اللهم اجعلْ صَلَوَاتِكَ وبَرَكاتِك على سيدنا محمد و آل سيدنا محمد، كما جعلتها على سيدنا إبراهيم وآل سيدنا إبراهيم إنك حميد مجيد، وبارك على سيدنا محمد و آل سيدنا محمد، كما باركت على سيدنا إبراهيم و آل سيدنا إبراهيم إنك حميد مجيد، اللهم صل على سيدنا محمد عبدِكَ وَرَسُولِكَ، وصل على المُؤمِنِينَ وَالمُؤمِنَاتِ، وَالمُسْلِمِينَ والمُسْلِمَاتِ، اللهم صل على سيدنا محمد وعلى آله عدد ما أحَاطَ بِهِ عِلْمُكَ، وأحصاهُ كِتَابَكَ ، وشَهِدَتْ بِهِ مَلائِكَتُكَ، صلاةً دائمةً تدوم بدوام مُلْكِ الله، اللهمَّ إِنِّي أَسْأَلُكَ بِأَسْمَائِكَ العِظَامِ، ما علمت منها وما لم أعلم، وبالأسماء التي سميت بها نَفْسَكَ، ما عَلِمْتُ منها وما لم أعلم، أن تصلي على سيدنا محمد عَبْدِكَ ونَبِيِّكَ وَرَسُولِكَ، عدد ما خلقت من قبل أن تكونَ السَّمَاءُ مَبْنِيَّةً والأرضُ مَدْحِيَّةً والجِبالُ مَرْسِيَّةً، والعُيونُ مُنْفَجِرَةً والأَنْهَارُ مُنْهَمِرَةً، والشمسُ مُشْرِقَةً والقمر مضيئاً والكواكب مستنيرة، والبحار مجرية والأشجار مثمرة، اللهم صل على سيدنا محمد عدد عِلْمِكَ، وصل على سيدنا محمد عدد حِلْمِكَ، وصل على سيدنا محمد عدد كلماتك، وصل على سيدنا محمد عدد نِعْمَتِكَ، وصل على سيدنا محمد عدد فَضْلِكَ، وصل على سيدنا محمد عدد جودك، وصل على سيدنا محمد عدد سماواتك، وصل على سيدنا محمد عدد أرْضِكَ، وصل على سيدنا محمد عدد ما خلقت في سبع سماواتِكَ مِنْ مَلائِكَتِكَ، وصل على سيدنا محمد عدد ما خلقتَ في أَرْضِكَ مِنَ الجِنِّ وَالإِنسِ وغيرهما، ومِنَ الوَحْشِ والطير وغيرهما، وصل على سيدنا محمد عدد ما جَرَى بِهِ القَلَمُ فِي عِلْمٍ غَيْبِكَ وما يجري به إلى يوم القيامة، وصل على سيدنا محمد عدد القطر والمطر، وصل على سيدنا محمد عدد من يحمدُكَ ويشكرك، ويُهلك ويُمجِدُكَ، ويَشْهَدُ أَنَّكَ أَنتَ اللهُ، وصل على سيدنا محمد عدد ما صليت عليه أنتَ ومَلائِكَتِكَ، وصل على سيدنا محمد عدد من صلى عليهِ مِنْ خَلْقِكَ، وصل على سيدنا محمد عددَ مَنْ لم يُصَلِّ عَليهِ مِنْ خَلْقِكَ وصل على سيدنا محمد عدد الجبال والرمال والحصى، وصل على سيدنا محمد عدد الشَّجَرِ وأوراقها والمدر وأثقالها، وصل على سيدنا محمد عدد كُلِّ سَنَة وما تَخْلُقُ فيها وما يموتُ فيها، وصل على سيدنا محمد عدد ما تَخْلُقُ كُلُّ يومٍ وما يموتُ فيه إلى يوم القيامة، اللهم وصل على سيدنا محمد عدد السَّحابِ الجَارِيَةِ ما بَيْنَ السَّمَاء والأرض وما تُمطِرُ مِنَ المياه، وصل على سيدنا محمد عدد الرِّيَاحِ المُسَخَّرَاتِ في مَشَارِقِ الأرض ومغاربها وجوفها وقبلتها، وصل على سيدنا محمد عدد نُجُومِ السَّمَاءِ، وصل على سيدنا محمد عدد ما خلقت في بِحارِكَ من الحيتان والدواب والمياه والرِّمَالِ وغيرِ ذَلِكَ، وصل على سيدنا محمد عدد النبات والحصى، وصل على سيدنا محمد عدد النمل، وصل على سيدنا محمد عدد المياه العذبة، وصل على سيدنا محمد عدد المياه الملحة، وصل على سيدنا محمد عدد نِعْمَتِكَ على جميع خَلْقِكَ، وصل على سيدنا محمد عدد نِقْمَتِكَ وعَذَابِكَ على مَنْ كَفَرَ بسيدنا محمد صلى الله عليه وسلم، وصل على سيدنا محمد عدد ما دامت الدنيا والآخرة، وصل على سيدنا محمد عدد ما دامت الخلائق في الجنة، وصل على سيدنا محمد عدد ما دامت الخلائق في النَّارِ، وصل على سيدنا محمد على قَدْرِ ما تُحِبُّه وترضاه، وصل على سيدنا محمد على قَدْرِ ما يُحِبُّكَ ويَرْضَاكَ، وصل على سيدنا محمد أَبَدَ الآبِدِينَ، وَأَنْزِلَهُ المَنْزَلَ المُقَرَّبَ عِنْدَكَ، وَأَعْطِهِ الوَسِيلَةَ والفَضِيلَةَ، والشَّفَاعَةَ والدَّرَجَةَ الرَّفِيعَةَ، والمقام المحمود الذي وَعَدْتَهُ، إِنَّكَ لا تخلف الميعاد، اللهم إني أسألك بأنَّكَ مالكي وسَيِّدِي ومَوْلايَ وثِقَتِي وَرَجَائِي، أسألُكَ بِحُرْمَةِ الشَّهْرِ الحَرَامِ والبَلَدِ الحَرَامِ، والمَشْعَرِ الحرام وقبر نبيك عليه السَّلامُ، أن تَهَبَ لِي مِنَ الخَيْرِ ما لا يَعْلَمُ عِلْمُهُ إلا أنتَ، وتَصْرِفَ عَنِّي مِنَ السُّوء ما لا يَعْلَمُ عِلْمُهُ إِلا أَنتَ، اللهم يا مَنْ وَهَبَ لسيدنا آدم سيدنا شيئاً، ولسيدنا إبراهيم سيدنا إسماعيل وسيدنا إسحاق، ورد سيدنا يوسف على سيدنا يعقوب، ويا مَنْ كَشَفَ البَلاءَ عَنْ سيدنا أَيُّوبَ، ويا مَنْ رَدَّ سيدنا مُوسَى إلى أُمِّهِ، ويا زَائِدَ سيدنا الخضر في عِلْمِهِ، ويا مَنْ وَهَبَ لسيدنا دَاوُدَ سيدنا سليمان، ولسيدنا زكرياء سيدنا يحيى، ولسيدتنا مريم سيدنا عيسى، ويا حافظ ابنة سيدنا شعيب، أسألك أن تصلي على سيدنا محمد وعلى جميع النَّبِيِّينَ والمُرْسَلِينَ، ويا مَنْ وَهَبَ لسيدنا محمد صلى الله عليه وسلم الشَّفَاعَةَ والدَّرَجَةَ الرَّفِيعَةَ، أَن تَغْفِرَ لِي ذُنُوبِي وَتَسْتُرَ لِي عُيُوبِي كلها، وتُجيرَنِي مِنَ النَّارِ وتُوجِبَ لِي رِضْوَانَكَ وأَمَانَكَ، وغُفْرَانَكَ وَإِحْسَانَكَ، وتُمتَعَنِي في جَنَّتِكَ مَعَ الَّذِينَ أَنْعَمْتَ عَليهِم مِنَ النَّبِيِّينَ والصِّدِّيقِينَ والشُّهَدَاءِ والصَّالِحِينَ، إِنَّكَ عَلى كُلِّ شَيءٍ قَدِيرُ، وصلى الله على سيدنا محمد وعلى آله ما أَزْعَجَتِ الرِّيَاحُ سَحَابِاً رُكَاماً، وَذَاقَ كُلُّ ذِي رُوح حماماً، وأوصِلِ السَّلامَ لأَهْلِ السَّلامِ فِي دَارِ السَّلامِ تَحِيَّةً وسَلاماً، اللهم أفْرِدْنِي لما خَلَقْتَنِي لَهُ وَلا تَشْعَلْنِي بِمَا تَكَفَّلْتَ لِي بِهِ، ولا تحرمني وأنا أسألك ولا تُعَذِّبني وأنا أسْتَغْفِرُكَ (ثلاثاً) ، اللهم صل على سيدنا محمد وعلى آله وسلم ، اللهم إني أسألك وأتوجه إليكَ بحبيبك المصْطَفَى عِنْدَكَ، يا حبيبنا يا سيدنا محمداً، إنا نَتَوَكَّلُ بِكَ إلى رَبِّكَ، فَاشْفَعْ لَنا عِنْدَ المَوْلَى العَظِيمِ يَا نِعْمَ الرَّسُولُ الطَّاهِرُ، اللهم شَفْعَهُ فِينَا بِجَاهِهِ عِنْدَكَ (ثلاثاً) ، واجعلنا مِنْ خَيرِ الْمُصَلِّينَ والمُسلِمِينَ عليهِ، وَمِنْ خَيرِ المُقَرَّبِينَ مِنْهُ وَالْوَارِدِينَ عَليهِ، وَمِنْ أَخْيَارِ الْمُحَبِينَ فيه والمحبوبينَ لَدَيْهِ، وفَرِّحْنَا بِهِ فِي عَرَصَاتِ القِيَامَةِ، واجعله لنا دليلاً إلى جَنَّةِ النَّعِيمِ، بِلا مَوْنَةٍ ولا مَشَقَّةٍ ولا مُنَاقَشَةِ الحِسَابِ واجعله مقبلاً علينا، ولا تجعله غاضباً علينا واغفر لنا ولوالدينا، ولجميع المُسلِمِينَ الأحياء منهم والميتين، وَآخِرُ دَعْوَانَا أَنِ الحَمدُ للهِ رَبِّ العَالَمِينَ. ابتداء الربع الرابع: فأسألك يا الله، يا الله، يا الله يا حي يا قيوم يا ذا الجلال والإكرام، لا إله إلا أنت سبحانك إني كنت من الظالمين، أسألك بما حمل كرسيك من عظمتك وجلالك، وبهائك وقدرتك وسلطانك، وبحق أسمائك المخزونة المكنونة المطهرة التي لم يطلع عليها أحد من خلقك، وبحق الإسم الذي وضعته على الليل فأظلم وعلى النهار فاستنار، وعلى السماوات فاستقلت وعلى الأرض فاستقرت، وعلى البحار فانفجرت وعلى العيون فنبعت وعلى السحاب فأمطرت، وأسألك بالأسماء المكتوبة في جبهة سيدنا جبريل عليه السلام، وبالأسماء المكتوبة في جبهة سيدنا إسرافيل عليه السلام وعلى جميع الملائكة، وأسألك بالأسماء المكتوبة حول العرش، وبالأسماء المكتوبة حول الكرسي، وأسألك باسمك العظيم الأعظم الذي سميت به نفسك، وأسألك بحق أسمائك كلها ما علمت منها وما لم أعلم، وأسألك بالأسماء التي دعاك بها سيدنا آدم عليه السلام، وبالأسماء التي دعاك بها سيدنا نوح عليه السلام، وبالأسماء التي دعاك بها سيدنا صالح عليه السلام، وبالأسماء التي دعاك بها سيدنا يونس عليه السلام، وبالأسماء التي دعاك بها سيدنا موسى عليه السلام، وبالأسماء التي دعاك بها سيدنا هارون عليه السلام، وبالأسماء التي دعاك بها سيدنا شعيب عليه السلام، وبالأسماء التي دعاك بها سيدنا إبراهيم عليه السلام، وبالأسماء التي دعاك بها سيدنا إسماعيل عليه السلام، وبالأسماء التي دعاك بها سيدنا داود عليه السلام، وبالأسماء التي دعاك بها سيدنا سليمان عليه السلام، وبالأسماء التي دعاك بها سيدنا زكرياء عليه السلام، وبالأسماء التي دعاك بها سيدنا يحيى عليه السلام، وبالأسماء التي دعاك بها سيدنا يوشع عليه السلام، وبالأسماء التي دعاك بها سيدنا الخضر عليه السلام، وبالأسماء التي دعاك بها سيدنا إلياس عليه السلام، وبالأسماء التي دعاك بها سيدنا اليسع عليه السلام، وبالأسماء التي دعاك بها سيدنا ذو الكفل عليه السلام، وبالأسماء التي دعاك بها سيدنا عيسى عليه السلام، وبالأسماء التي دعاك بها سيدنا محمد صلى الله عليه وسلم نبيك ورسولك، وحبيبك وصفيكَ، يا من قال وقوله الحق، (واللهُ خَلَقَكُمْ وَمَا تَعْمَلُونَ)، ولا يصدرُ عن أحد من عبيده قول ولا فعل ولا حركةً ولا سكون، إلا وقد سبق في علمه وقضائه وقدره كيف يكون، كما ألهمتني وقضيت لي يجمع هذا الكتاب، ويسَّرْتَ عَلَيَّ فيه الطريق والأسباب، ونفيت عن قلبي في هذا النبي الكريم الشك والارتياب، وغلبت حبه عندي على حب جميع الأقرباء والأحباء، أسألك يا الله، يا الله يا الله، أن ترزقني وكل من أحبه واتبعه شفاعته ومرافقته يوم الحساب، من غير مناقشة ولا عذاب ولا توبيخ ولا عتاب، وأن تغفر لي ذنوبي وتستر لي عيوبي يا وهاب يا غفار، وأن تنعمني بالنظر إلى وجهك الكريم في جملة الأحباب يوم المزيد والثواب، وأن تتقبل مني عملي، وأن تعفو عما أحاط علمك به من خطيئتي ونسياني وزلي، وأن تبلغني من زيارة قبره والتسليم عليه وعلى صاحبيه غاية أملي، بمنك وفضلك وجودك وكرمك، يا رؤوف، يا رحيم، يا ولي، وأن تجازيه عني وعن كل من آمن به واتبعه من المسلمين والمسلمات، الأحياء منهم والأموات، أفضل وأتم وأعم ما جازيت به أحداً من خلقك، يا قوي، يا عزيز، يا علي، وأسألك اللهم بحق ما أقسمت به عليكَ، أنْ تُصَلِّي على سيدنا محمد وعلى آل سيدنا محمد عدد ما خلقت من قبل أن تكون السماء مبنيةً والأرض مدحية، والجبال علوية والعيون منفجرة، والبحار مسخرة والأنهار منهمرة، والشمس مضحية والقمر مضيئاً والنجم منيراً ولا يعلم أحد حيث تكون إلا أنتَ، وأنْ تُصَلِّي عليه وعلى آلهِ عَدَدَ كلامك، وأنْ تُصَلِّي عليه وعلى آله عَدَدَ آيات القرآن وحروفه وأن تصلي عليه وعلى آله عَدَدَ من يصلي عليه، وأن تصلي عليه وعلى آله عدد من لم يصل عليه، وأنْ تُصَلِّي عليه وعلى آله ملء أرضك، وأنْ تُصَلِّي عليه وعلى آله عَدَدَ ما جرى به القلم في أم الكتاب، وأن تصلي عليه وعلى آله عَدَدَ ما خلقت في سبع سماواتك، وأنْ تُصَلِّي عليه وعلى آله عَدَدَ ما أنت خالقه فيهن إلى يوم القيامة، في كل يوم ألف مرة، وأنْ تُصَلِّي عليه وعلى آله عَدَدَ قطر المطر، وكل قطرة قطرت من سمائك إلى أرضك، من يوم خلقت الدنيا إلى يوم القيامة، في كل يوم ألف مرة، وأنْ تُصَلِّي عليه وعلى آله عَدَدَ من سبحك وقدسك، وسجد لك وعظمك، من يوم خلقت الدنيا إلى يوم القيامة، في كل يوم ألف مرة، وأن تصلي عليه وعلى آله عَدَدَ كل سنة خلقتهم فيها، من يوم خلقت الدنيا إلى يوم القيامة، في كل يوم ألف مرة، وأن تصلي عليه وعلى آله عَدَدَ السحاب الجارية، وأن تصلي عليه وعلى آله عَدَدَ الرياح الذارية، من يوم خلقت الدنيا إلى يوم القيامة، في كل يوم ألف مرة، وأنْ تُصَلِّي عليه وعلى آلهِ عَدَدَ ما هبت الرياح عليه، وحركته من الأخ الأغصان والأشجار، وأوراق الثمار والأزهار، عدَدَ ما خلقت على قرار أرضك وما بين سماواتك، من يوم خلقت الدنيا إلى يوم القيامة، في كل يوم ألف مرة، وأن تصلي عليه وعلى آله عَدَدَ أمواج بحارك، من يوم خلقت الدنيا إلى يوم القيامة، في كل يوم ألف مرة، وأنْ تُصَلِّي عليه وعلى آله عَدَدَ الرمل والحصى وكل حجر ومدر خلقته في مشارق الأرض ومغاربها، سهلها وجبالها وأوديتها، من يوم خلقت الدنيا إلى يوم القيامة، في كل يوم ألف مرة، وأنْ تُصَلِّي عليه وعلى آلهِ عَدَدَ نبات الأرض في قبلتها وجوفها، وشرقها وغربها، وسهلها وجبالها، من شَجَرٍ وثَمر وأوراق وزرع، وجميع ما أخرجت وما يخرج منها من نباتها وبركاتها، من يوم خلقت الدنيا إلى يوم القيامة، في كل يوم ألف مرة، وأن تصلي عليه وعلى آله عَدَدَ ما خلقت من الإنس والجن والشياطين، وما أنت خالقه منهم إلى يوم القيامة، في كل يوم ألف مرة، وأن تُصَلِّي عليه وعلى آله عَدَدَ كلِّ شعرة في أبدانهم ووجوههم وعلى رؤوسهم، منذ خلقت الدنيا إلى يوم القيامة، في كل يوم ألف مرة، وأنْ تُصَلِّي عليه وعلى آله عَدَدَ أنفاسهم وألفاظهم وألحاظِهِمْ ، من يوم خلقت الدنيا إلى يوم القيامة، في كل يوم ألف مرة، وأن تصلي عليه وعلى آله عَدَدَ طيران الجن وخفقان الإنس، من يوم خلقت الدنيا إلى يوم القيامة، في كل يوم ألف مرة، وأن تصلي عليه وعلى آله عدد كل بهيمة خلقتها على أرضك صغيرةً أو كبيرةً، في مشارق الأرض ومغاربها، مما علم ومما لا يعلم علمه إلا أنت، من يوم خلقت الدنيا إلى يوم القيامة، في كل يوم ألف مرة، وأن تصلي عليه وعلى آله عَدَدَ من صلى عليه، وعَدَدَ من لم يُصَلِّ عليه، وعَدَدَ مِنْ يُصَلِّي عليه إلى يوم القيامة، في كل يوم ألف مرة، وأن تصلي عليه وعلى آله عَدَدَ الأحياء والأمواتِ، وعَدَدَ ما خلقت من حيتان وطير ونمل ونحل وحشرات، وأن تصلي عليه وعلى آله في الليل إذا يغشى والنهار إذا تجلى، وأن تصلي عليه وعلى آله في الآخرة والأولى، وأن تُصَلِّي عليه وعلى آله منذ كان في المهد صبياً، إلى أن صار كهلاً مهدياً، فقبضته إليك عدلاً مرضياً لتبعثه شفيعاً، وأن تصلي عليه وعلى آله عدد خلقك ورضاء نفسك، وزنة عرشك ومداد كلماتك، وأن تعطيه الوسيلة والفضيلة، والدرجة الرفيعة والحوض المورود، والمقام المحمود والعز الممدود، وأن تعظم برهانه وأنْ تُشَرِّفَ بنيانه وأن ترفع مكانه، وأن تستعملنا يا مولانا بسنته وأن تميتنا على ملته، وأن تحشرنا في زمرته وتحت لوائه، وأن تجعلنا من رفقائه وأن توردنا حوضه، وأن تسقينا بكأسه وأن تنفعنا بمحبته، وأن تتوب علينا وأن تعافينا من جميع البلاء والبلواء والفتن ما ظهر منها وما بطن، وأن ترحمنا، وأن تعفو عنا، وتغفر لنا ولجميع المؤمنين والمؤمنات، والمسلمين والمسلمات، الأحياء منهم والأموات، والحمد لله رب العالمين، وهو حسبي ونعم الوكيل، ولا حول ولا قوة إلا بالله العلي العظيم.''',
  ),

  // ══════════════════════════════════════════
  // الحزب السابع — يوم الأحد
  // ══════════════════════════════════════════
  DalailDay.sunday: DalailDaySection(
    day: DalailDay.sunday,
    hizb: 'الحزب السابع',
    content: '''بسم الله الرحمن الرحيم اللهم صل على سيدنا محمد وعلى آل سيدنا محمد ما سجعت الحمائم وحمت الحوائم، وسرحت البهائم ونفعتِ التمائم، وشُدَّتِ العمائم وتمتِ النوائم، اللهم صل على سيدنا محمد وعلى آل سيدنا محمد ما أبلج الإصباحُ وهَبَّتِ الرياح، ودَبَّتِ الأشباح وتعاقب الغدو والرواح، وتقلدَتِ الصفاح واعتقلت الرماح، وصحتِ الأجساد والأرواح، اللهم صل على سيدنا محمد وعلى آل سيدنا محمد ما دارت الأفلاكُ ودَجَتِ الأحلاكُ وسَبحَتِ الأملاك، اللهم صل على سيدنا محمد وعلى آل سيدنا محمد كما صليت على سيدنا إبراهيم، وبارك على سيدنا محمد وعلى آل سيدنا محمد كما باركت على سيدنا إبراهيم في العالمين إنك حميد مجيد، اللهم صل على سيدنا محمد وعلى آل سيدنا محمد ما طَلَعَتِ الشمس وما صليت الخمس، وما تَأَلَّقَ بَرْقُ وتَدَفَّقَ وَدْقُ وما سَبَّحَ رَعْدُ، اللهم صل على سيدنا محمد وعلى آل سيدنا محمد ملء السماوات والأرض وملء ما بينهما وملء ما شِئْتَ من شيء بعد، اللهم كما قام بأعباء الرسالة، واستنقذ الخلق من الجهالة، وجاهد أهل الكفر والضلالة، ودعا إلى توحيدك، وقاسى الشدائد في إرشاد عبيدك، فأعطه اللهم سؤله وبلغه مأموله، وآته الوسيلة والفضيلة والدرجة الرفيعة، وابعثه المقام المحمود الذي وعدته، إنك لا تخلف الميعاد، اللهم واجعلنا من المتبعين لشريعته، المتصفين بمحبته، المهتدين بهديه وسيرته، وتوفنا على سنته ولا تحرمنا فضل شفاعته، واحشرنا في أتباعه الغر المحجلين، وأشياعه السابقين، وأصحاب اليمين، يا أرحم الراحمين، اللهم صلّ على ملائكتك والمقربين، وعلى أنبيائك والمرسلين، وعلى أهل طاعتك أجمعين، واجعلنا بالصلاة عليهم من المرحومين، اللهم صل على سيدنا محمد المبعوث من تِهامة، والآمر بالمعروف والاستقامة، والشفيع لأهل الذنوب في عرصات القيامة، اللهمَّ أَبْلِغْ عَنَّا نَبِيَّنَا وشَفيعنا وحبيبنا أفضل الصلاة والتسليم، وابعثه المقام المحمود الكريم، وآته الوسيلة والفضيلة والدرجة الرفيعة التي وعدته في الموقف العظيم، وصل اللهم عليه صلاةً دائمةً متصلةً تتوالى وتدوم، اللهم صل عليه وعلى آله ما لاح بارقُ وذَرَّ شارق، ووقب غاسق وانهمر وادق، وصل عليه وعلى آله ملء اللوح والفضاء، ومثل نجوم السماء، وعدد القطر والمطر والحصى، وصل عليه وعلى آله صلاةً لا تعد ولا تحصى، اللهم صلّ عليه زنة عرشك، ومبلغ رضاك، ومداد كلماتك، ومنتهى رحمتك، اللهم صل عليه وعلى آله وأزواجه وذريته، وبارك عليه وعلى آله وأزواجه وذريته، كما صليت وباركت على سيدنا إبراهيم وعلى آل سيدنا إبراهيم إنك حميد مجيد، وجازه عنا أفضل ما جازيت نبياً عن أمته، واجعلنا من المهتدين بمنهاج شريعته، واهدنا بهديه، وتوفنا على ملته، واحشرنا يوم الفزع الأكبر من الآمنين في زمرته، وأمتنا على حبه وحب آله وأصحابه وذريته، اللهم صل على سيدنا محمد أفضل أنبيائك، وأكرم أصفيائك، وإمام أوليائك، وخاتم أنبيائك، وحبيب رب العالمين، وشهيد المرسلين، وشفيع المذنبين، وسيد ولد آدم أجمعين، المرفوع الذكر في الملائكة المقربين، البشير النذير، السراج المنير، الصادق الأمين، الحق المبين، الرؤوف الرحيم، الهادي إلى الصراط المستقيم، الذي آتيته سبعاً من المثاني والقرآن العظيم، نبي الرحمة وهادي الأمة، أول من تنشق عنه الأرض ويدخل الجنة، والمؤيد بسيدنا جبريل وسيدنا ميكائيل، المبشر به في التوراة والإنجيل، المصطفى المجتبى المنتخب أبي القاسم، سيدنا محمد بن عبد الله بن عبد المطلب بن هاشم، اللهم صل على ملائكتك والمقربين الذين يسبحون الليل والنهار لا يفترون، ولا يعصون الله ما أمرهم ويفعلون ما يؤمرون، اللهم وكما اصطفيتهم سُفَرَاءَ إِلى رُسُلِكَ وأَمَنَاءَ على وَحْيِكَ وَشُهَدَاءَ على خلقك، وخرقت لهم كُنفَ وأطلعتهم على مكنون غيبك، واخترت منهم خزنة لجنتك وحملةً لعرشك، وجعلتهم من أكثر جنودك، وفَضَّلْتهم على الورى، وأسكنتهم السماوات العلى، ونزهتهم عن المعاصي والدناءات، وقدستهم عن النقائص والآفات، فصل عليهم صلاةً دائمة تزيدهم بها فضلاً، وتجعلنا لاستغفارهم بها أهلاً، اللهم وصل على جميع أنبيائك ورسلك، الذين شرحت صدورهم وأودعتهم حكمتك وطوقتهم نبوتك وأنزلت عليهم كتبك، وهديت بهم خلقك ودعوا إلى توحيدك، وشَوقُوا إلى وعدك وخوفوا من وعيدك، وأرشدوا إلى سبيلك وقاموا بحجتك ودليلك، وسلم اللهم عليهم تسليماً، وهب لنا بالصلاة عليهم أجراً عظيماً، اللهم صل على سيدنا محمد وعلى آل سيدنا محمد صلاة دائمةً مقبولة تؤدي بها عنا حقه العظيم، اللهم صل على سيدنا محمد صاحب الحسن والجمال والبهجة والكمال، والبهاء والنور والوِلْدَانِ والحور، والغرف والقصور واللسان الشكور والقلب المشكور، والعلم المشهور والجيش المنصور، والبنين والبنات، والأزواج الطاهرات، والعلو على الدرجات، والزمزم والمقام والمشعر الحرام، واجتناب الآثام وتربية الأيتام، والحج وتلاوة القرآن، وتسبيح الرحمن وصيام رمضان، واللواء المعقود، والكرم والجود، والوفاء بالعهود، صاحب الرغبة والترغيب والبغلة والنجيب، والحوض والقضيب، النبي الأواب، الناطق بالصواب المنعوت في الكتاب، النبي عبد الله النبي كنز الله النبي حجة الله، النبي من أطاعه فقد أطاع الله، ومن عصاه فقد عصى الله، النبي العربي، القرشي الزمزمي ، المكي التهامي، صاحب الوجه الجميل، والطرف الكحيل، والخد الأسيل، والكوثر والسلسبيل، قاهر المضادين مبيد الكافرين، وقاتل المشركين، قائد الغر المحجلين إلى جنات النعيم وجوار الكريم، صاحب سيدنا جبريل عليه السلام، ورسول رب العالمين، وشفيع المذنبين، وغاية الغمام، ومصباح الظلام، وقمر التمام، صلى الله عليه وعلى آله المصطفين من أطهر جبلة ، صلاة دائمةً على الأبدِ غيرَ مُضْمَحِلَّةٌ، صلى الله عليه وعلى آله صلاةً يتجدد بها حبوره، ويشرف بها في الميعاد بعثه ونشوره، فصلى الله عليه وعلى آله الأنجم الطوالع ، صلاةً تجود عليهم أجود الغُيُوثِ الهَوَامِعِ، أَرْسَلَهُ من أرجح العرب ميزاناً وأوضحها بياناً، وأفصحها لساناً وأشمخها إيماناً وأعلاها مقاماً وأحلاها كلاماً، وأوفاها ذِمَامَاً وأَصْفَاهَا رَغَامَاً، فَأَوْضَحَ الطريقة، ونصح الخليقة، وشهر الإسلام وكسر الأصنام، وأظهر الأحكام وحَظَرَ الحرام وعم بالإنعام، صلى الله عليه وعلى آله في كلِّ مَحْفَلٍ ومَقَامٍ، أفضل الصلاة والسلام، صلى الله عليه وعلى آله عوداً وبدءاً صلاةً تكونُ ذَخِيرَةً وَوَرْداً، صلى الله عليه وعلى آله صلاة تامة زاكية، وصلى الله عليه وعلى آله صلاةً يتبعها روح وريحان، ويعقبها مَغْفِرَةً ورِضْوَانٌ، وصلى الله على أفضل من طاب منهُ النَّجَارُ، وَسَمَا بِهِ الفَخَارُ، واستنارَتْ بنور جبينه الأقمار، وتضاءلت عند جود يمينه الغمائم والبحار، سيدنا ونبينا محمد الذي باهر آياته أضاءت الأنجاد والأغوار، وبمعجزات آياته نطق الكتاب وتواترت الأخبار، صلى الله عليه وعلى آله وأصحابه الذين هاجروا لنصرته، ونصروه في هجرته، فنعم المهاجرون ونعم الأنصار، صلاة نامية دائمة ما سمعت في أيكها الأطيار، وجمعت بوبلها الديمة المدرار، ضاعف الله عليه دائم صلواته، اللهم صل على سيدنا محمد وعلى آله الطيبين الكرام، صلاة موصولة دائمة الاتصال بدوام ذي الجلال والإكرام، اللهم صل على سيدنا محمد الذي هو قطب الجلالة، وشمس النبوة والرسالة، والهادي من الضلالة، والمنقذ من الجهالة، صلى الله عليه وسلم صلاة دائمة الاتصال والتوالي، متعاقبةً بتعاقب الأيام والليالي، اللهم صل على سيدنا محمد النبي الزاهد، رسول المَلِكِ الصمد الواحد، صلى الله عليه وسلم صلاةً دائمةً إلى منتهى الأبد بلا انقطاع ولا نفاد، صلاةً تنجينا بها من حر جهنم وبئس المهاد، اللهم صل على سيدنا محمد النبي الأمي وعلى آله وسلم، صلاةً لا يُحصى لها عدد، ولا يعد لها مدد، اللهم صل على سيدنا محمد صلاة تكرم بها مثواه، وتبلغ بها يوم القيامة من الشفاعة رضاه، اللهم صل على سيدنا محمد النبي الأصيل السيد النبيل، الذي جاء بالوحي والتنزيل وأوضح بيان التأويل، وجاءه الأمين سيدنا جبريل عليه السلام بالكرامة والتفضيل، وأسرى به الملك الجليل في الليل البهيم الطويل، فكشف له عن أعلى الملكوت وأراه سناء الجبروت، ونظر إلى قدرة الحي الدائم الباقي الذي لا يموت، صلى الله عليه وسلم صلاةً مقرونة بالجمال، والحسن والكمال والخير والإفضال، اللهم صل على سيدنا محمد وعلى آل سيدنا محمد عدد الأقطار، وصل على سيدنا محمد وعلى آل سيدنا محمد عدد ورق الأشجار، وصل على سيدنا محمد وعلى آل سيدنا محمد عَدَدَ زبد البحار، وصل على سيدنا محمد وعلى آل سيدنا محمد عدد الأنهار، وصل على سيدنا محمد وعلى آل سيدنا محمد عَدَدَ رمل الصحاري والقفار، وصل على سيدنا محمد وعلى آل سيدنا محمد عدد ثقل الجبال والأحجار، وصل على سيدنا محمد وعلى آل سيدنا محمد عَدَدَ أهل الجنة وأهل النار، وصل على سيدنا محمد وعلى آل سيدنا محمد عدد الأبرار والفجار، وصل على سيدنا محمد وعلى آل سيدنا محمد عَدَدَ ما يختلف به الليل والنهار، واجعل اللهم صلاتنا عليه حجاباً من عذاب النار، وسبباً الإباحة دار القرار، إنك أنت العزيز الغفار، وصلى الله على سيدنا محمد وعلى آله الطيبين وذريته المباركين، وصحابته الأكرمين وأزواجه أمهات المؤمنين، صلاةً موصولةً تتردد إلى يوم الدين، اللهم صل على سيد الأبرار، وزَيْنِ المرسلين الأخيار، وأكرم من أظلم عليه الليل وأشرق عليه النهار) (ثلاثاً) ، اللهم يا ذا المن الذي لا يكافى امتنانه، والطول الذي لا يُجازى إنعامه وإحسانه، نسألُكَ بِكَ ولا نسألُكَ بأحد غيرك، أن تطلق ألسنتنا عند السؤال، وتوفقنا لصالح الأعمال، وتجعلنا من الآمنين يومَ الرَّجفِ والزلزال، يا ذا العزة والجلال، أسألك يا نور النور، قبل الأزمنة والدهور، أنت الباقي بلا زوال، الغني بلا مثال، القدوس الطاهر، العلي القاهر، الذي لا يحيط به مكان، ولا يشتمل عليه زمان، أسألك بأسمائك الحسنى كلها، وبأعظم أسمائك إليك وأشرفها عندك منزلةً وأجزلها عندك ثواباً وأسرعها إجابة، وباسمك المخزون المكنون، الجليل الأجل، الكبير الأكبر، العظيم الأعظم، الذي تحبه وترضى عمن دعاك به وتستجيب له دعاءه، أسألك اللهم بلا إله إلا أنتَ الحنان المنان، بديع السماوات والأرض، ذو الجلال والإكرام، عالم الغيب والشهادة، الكبير المتعال، وأسألك باسمك العظيم الأعظم، الذي إذا دعيت به أجبت، وإذا سئلت به أعطيت، وأسألك باسمك الذي يذلُّ لعظمته العظماء والملوك والسباع والهوام، وكلُّ شيء خلقته يا الله، يا رب استجب دعوتي، يا من له العزة والجبروت، يا ذا الملك والملكوت، يا من هو حي لا يموت، سبحانك ربي ما أعظم شأنك، وأرفع مكانك أنت ربي، يا متقدساً في جبروته، إليك أرغبُ، وإياك أرهب، يا عظيم يا كبير، يا جبار يا قادر يا قوي، تباركت يا عظيم، تعاليت يا عليم، سبحانك يا عظيم، سبحانك يا جليل، أسألك باسمك العظيم التام الكبير، أن لا تسلط علينا جباراً عنيداً، ولا شيطاناً مريداً، ولا إنساناً حسوداً، ولا ضعيفاً من خلقك ولا شديداً، ولا باراً ولا فاجراً ولا عبيداً ولا عنيداً، اللهم إني أسألك فإني أشهد أنك أنت الله الذي لا إله إلا أنت الواحد الأحد الصمد، الذي لم يلد ولم يولد، ولم يكن له كفواً أحد، يا هو يا من لا هو إلا هو، يا من لا إله إلا هو، يا أزلي يا أبدي يا دهري يا ديمومي، يا من هو الحي الذي لا يموت، يا إلهنا وإله كل شيء إلها واحداً، لا إله إلا أنت، اللهم فاطر السماوات والأرض، عالم الغيب والشهادة، الرحمن الرحيم، الحي القيوم الديان، الحنان المنان، الباعث الوارث، ذا الجلال والإكرام، قلوب الخلائق بيدك، نواصيهم إليك، فأنت تزرع الخير في قلوبهم، وتمحو الشر إذا شئتَ مِنْهُمْ، فأسألك اللهم أن تمحو من قلبي كل شيء تكرهه، وأن تحشو قلبي من خشيتك، ومعرفتك ورهبتكَ، والرغبة فيما عندك، والأمن والعافية، واعطف علينا بالرحمة والبركة منك، وألهمنا الصواب والحكمة، فنسألك اللهم علم الخائفين، وإنابة المخبتين، وإخلاص الموقنين، وشكر الصابرين، وتوبة الصديقين، ونسألك اللهم بنور وجهك الذي ملأ أركان عرشك، أن تزرع في قلبي معرفتك حتى أَعْرِفَكَ حق معرفتك، كما ينبغي أن تعرف به، وصلى الله على سيدنا محمد خاتم النبيين، وإمام المرسلين، وعلى آله وصحبه وسلم تسليماً، والحمد لله رب العالمين.''',
  ),

